extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var player_source := source_of("res://player.gd")
	check("no_label_in_player", not player_source.contains("EnergyLabel"), "player.gd non deve fare riferimento a EnergyLabel")
	check("no_bar_in_player", not player_source.contains("EnergyBar"), "player.gd non deve fare riferimento a EnergyBar")

	var world := await instantiate_main_scene()
	if not check("world_ok", world != null, "world.tscn deve istanziarsi correttamente"):
		return

	var player := find_by_name(world, "Player")
	var hud := find_by_name(world, "HUD")
	if not check("istanze_trovate", player != null and hud != null, "World deve contenere sia Player sia HUD"):
		return

	var label := find_by_name(hud, "EnergyLabel") as Label
	var bar := find_by_name(hud, "EnergyBar") as ProgressBar
	if not check("controlli_in_hud", label != null and bar != null, "HUD deve contenere EnergyLabel e EnergyBar"):
		return

	var max_val = get_prop(player, "max_energy", 100)
	call_if_exists(player, "use_energy", [35])
	await wait_frames(2)
	var current_val = get_prop(player, "energy", 65)
	var expected_text := "Energia: %d/%d" % [current_val, max_val]
	check("label_aggiornata", label.text == expected_text, "Dopo use_energy(35) il testo deve mostrare '%s' (è '%s')" % [expected_text, label.text])
	check("bar_aggiornata", is_equal_approx(bar.value, float(current_val)), "Dopo use_energy(35) la barra deve valere %d (vale %.1f)" % [current_val, bar.value])
